-- ---------------- Ajuste de secuencias ----------------
-- Como se insertaron IDs explicitos, las secuencias deben avanzar al maximo
-- usado; de lo contrario el primer INSERT desde la aplicacion chocaria con
-- una llave primaria ya existente.
SELECT setval(pg_get_serial_sequence('rol', 'id'), (SELECT MAX(id) FROM rol));
SELECT setval(pg_get_serial_sequence('usuario', 'id'), (SELECT MAX(id) FROM usuario));
SELECT setval(pg_get_serial_sequence('categoria', 'id'), (SELECT MAX(id) FROM categoria));
SELECT setval(pg_get_serial_sequence('producto', 'id'), (SELECT MAX(id) FROM producto));
SELECT setval(pg_get_serial_sequence('proveedor', 'id'), (SELECT MAX(id) FROM proveedor));
SELECT setval(pg_get_serial_sequence('cliente', 'id'), (SELECT MAX(id) FROM cliente));
SELECT setval(pg_get_serial_sequence('compra', 'id'), (SELECT MAX(id) FROM compra));
SELECT setval(pg_get_serial_sequence('detalle_compra', 'id'), (SELECT MAX(id) FROM detalle_compra));
SELECT setval(pg_get_serial_sequence('lote', 'id'), (SELECT MAX(id) FROM lote));
SELECT setval(pg_get_serial_sequence('venta', 'id'), (SELECT MAX(id) FROM venta));
SELECT setval(pg_get_serial_sequence('detalle_venta', 'id'), (SELECT MAX(id) FROM detalle_venta));
SELECT setval(pg_get_serial_sequence('detalle_venta_lote', 'id'), (SELECT MAX(id) FROM detalle_venta_lote));
SELECT setval(pg_get_serial_sequence('movimiento_inventario', 'id'), (SELECT MAX(id) FROM movimiento_inventario));
SELECT setval(pg_get_serial_sequence('bitacora', 'id'), (SELECT MAX(id) FROM bitacora));
SELECT setval('seq_numero_factura', (SELECT MAX(numero_factura) FROM venta));
